// Shape of the asset calibration record (generated by scripts/calibrate-model.ts from the committed GLB).
export type Tuple3 = [number, number, number];
export type Tuple4 = [number, number, number, number];

export interface ModelCalibration {
  asset: {
    file: string;
    bytes: number;
    sha256: string;
    joints: number;
    triangles: number;
    meshes: string[];
    morphTargets: string[];
    animations: number;
    /** max |jointWorld x inverseBind - I|: the bind pose is the node rest pose. */
    bindRestMaxErr: number;
  };
  frame: {
    note: string;
    /** GLB world point that becomes the body-local origin (x = 0, the proxy rest height, the hips joint depth). */
    origin: Tuple3;
    restOriginY: number;
    /** Local X sign of the anatomical right side (-1: the GLB's Right* bones lie on -X while facing +Z). */
    rightSignX: 1 | -1;
  };
  /** Skeleton hierarchy (joint -> parent joint; null for the root). */
  parents: Record<string, string | null>;
  /** Rest joint position (body-local) and world rest rotation (GLB axes), per joint. */
  restJoints: Record<string, { p: Tuple3; q: Tuple4 }>;
  /** Simulation landmarks at rest, body-local (named by the anatomical side). */
  landmarks: Record<string, Tuple3>;
  lengths: { upperArm: number; forearm: number; palmExtension: number; thigh: number; shin: number; asymmetryM: number };
  radii: { upperArm: number; forearm: number; thigh: number; shin: number; palm: number; head: number };
  /** Glove landmarks along the forearm axis from the wrist (m). */
  glove: { vertices: number; palmCenterAlongM: number; tipAlongM: number; baseAlongM: number };
  /** Shoe box in the rest shin frame (origin ankle, +Y up the shin, X knee axis, Z forward); sole and ankle heights. */
  shoe: { vertices: number; centerShin: Tuple3; halfExtents: Tuple3; soleAboveFloorM: number; ankleAboveFloorM: number };
  torso: { vertices: number; center: Tuple3; halfExtents: Tuple3 };
  pelvis: { vertices: number; center: Tuple3; halfExtents: Tuple3 };
  /**
   * Arm self-clearance trunk: the Hips/Spine-dominant skin (body-local, Basis shape) as stacked convex slabs, bottom up;
   * each piece's points are its convex hull's vertices over `yRange` widened by the slab overlap.
   */
  trunkHull: { vertices: number; pieces: { yRange: [number, number]; points: Tuple3[] }[] };
  helmet: { shellVertices: number; center: Tuple3; boundsMin: Tuple3; boundsMax: Tuple3 };
  /** Rest segment frames (body-local rotations) in the PhysicalPose/ragdoll limb convention. */
  segmentRest: Record<string, Tuple4>;
  keyColors: Record<string, string>;
}
